def check(ctx):
    history = ctx['CreditReport.housing_history_rating']
    purpose = ctx['LoanCore.loan_purpose']
    cltv_raw = ctx['LoanCore.cltv_percent']

    missing = rules_lib.gaps(history=history, purpose=purpose, cltv_raw=cltv_raw)
    if missing:
        return rules_lib.unknown(*missing)

    cltv = rules_lib.percent(cltv_raw, 'percent')
    if cltv is None:
        return rules_lib.unknown('LoanCore.cltv_percent')

    if rules_lib.same(purpose, 'Purchase'):
        purchase = True
    elif rules_lib.same(purpose, 'Refi R/T', 'Refi C/O'):
        purchase = False
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    if rules_lib.same(history, '1x30x12'):
        maximum = 80 if purchase else 75
    elif rules_lib.same(history, '0x60x12'):
        maximum = 75 if purchase else 70
    elif rules_lib.same(history, '0x90x12'):
        maximum = 65
    elif rules_lib.same(history, '0x120x12'):
        return False
    else:
        return rules_lib.unknown('CreditReport.housing_history_rating')

    return cltv <= maximum

import decimal
import rules_lib


def check(ctx):
    has_event = ctx['Borrower.has_short_sale_dil_or_modification']
    missing = rules_lib.gaps(has_event=has_event)
    if missing:
        return rules_lib.unknown(*missing)

    has_event = rules_lib.flag(has_event)
    if has_event is None:
        return rules_lib.unknown('has_event')
    if not has_event:
        return True

    months = ctx['Borrower.months_since_short_sale_dil_or_modification']
    purpose = ctx['LoanCore.loan_purpose']
    missing = rules_lib.gaps(months=months, purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    try:
        months = decimal.Decimal(str(months))
        if not months.is_finite():
            return rules_lib.unknown('months')
    except (decimal.InvalidOperation, TypeError, ValueError):
        return rules_lib.unknown('months')

    if rules_lib.same(purpose, 'purchase'):
        if months < 12:
            maximum = 75
        elif months < 24:
            maximum = 80
        else:
            return True
    elif rules_lib.same(purpose, 'Refi R/T', 'Refi C/O'):
        if months < 12:
            maximum = 70
        elif months < 24:
            maximum = 75
        else:
            return True
